use super::*;
#[kani::proof]
#[kani::unwind(33)]
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NHP_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NHP_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NHP_KMX::KMX_realloc)]
fn association(){
 let digest:[u8;32]=kani::any();let mut seed:[u8;32]=kani::any();
 let chunk:usize=kani::any();kani::assume(chunk<4);let mut word:u64=kani::any();kani::assume(word<(1u64<<56));
 let q:usize=kani::any();kani::assume(q<32);let prior_digest=digest[q];let prior_seed=seed[q];let prior_word=word;
 let mut group:usize=kani::any();kani::assume(group<8);let prior_group=group;let position=8*chunk+group;let quotient=match group {0=>word/562949953421312u64,1=>word/4398046511104u64,2=>word/34359738368u64,3=>word/268435456u64,4=>word/2097152u64,5=>word/16384u64,6=>word/128u64,7=>word/1u64,_=>unreachable!()};let expected=(quotient%128) as u8;
 seed[8 * chunk + group] = ((word >> (7 * (7 - group))) & 0x7f) as u8;
            group += 1;

 assert!(group==prior_group+1);assert!(word==prior_word);assert!(seed[position]==(expected^1));assert!(seed[position]<128);assert!(seed[q]==if q==position {expected}else{prior_seed});
 assert!(digest[q]==prior_digest);
}
